/**
 * iOS launch images (apple-touch-startup-image). iOS needs an exact-size image per
 * device; these are generated by `pnpm icons` (scripts/generate-icons.mjs) from the
 * same list. Portrait only — iOS falls back to the background colour otherwise.
 */
export const splashDevices = [
  { w: 375, h: 667, dpr: 2 }, // iPhone SE / 8
  { w: 414, h: 896, dpr: 2 }, // iPhone 11 / XR
  { w: 375, h: 812, dpr: 3 }, // iPhone X / XS / 11 Pro / 12-13 mini
  { w: 414, h: 896, dpr: 3 }, // iPhone XS Max / 11 Pro Max
  { w: 390, h: 844, dpr: 3 }, // iPhone 12 / 13 / 14
  { w: 428, h: 926, dpr: 3 }, // iPhone 12-13 Pro Max / 14 Plus
  { w: 393, h: 852, dpr: 3 }, // iPhone 14 Pro / 15 / 15 Pro / 16
  { w: 430, h: 932, dpr: 3 }, // iPhone 14 Pro Max / 15 Plus / 15 Pro Max / 16 Plus
  { w: 402, h: 874, dpr: 3 }, // iPhone 16 Pro / 17 / 17 Pro
  { w: 440, h: 956, dpr: 3 }, // iPhone 16 Pro Max / 17 Pro Max
  { w: 420, h: 912, dpr: 3 }, // iPhone Air
  { w: 744, h: 1133, dpr: 2 }, // iPad mini
  { w: 820, h: 1180, dpr: 2 }, // iPad Air / iPad 10th
  { w: 834, h: 1194, dpr: 2 }, // iPad Pro 11
  { w: 834, h: 1210, dpr: 2 }, // iPad Pro 11 (M4)
  { w: 1024, h: 1366, dpr: 2 }, // iPad Pro 12.9
  { w: 1032, h: 1376, dpr: 2 }, // iPad Pro 13 (M4)
] as const;

export const splashScreens = splashDevices.map(({ w, h, dpr }) => ({
  url: `/splash/splash-${w * dpr}x${h * dpr}.png`,
  media: `(device-width: ${w}px) and (device-height: ${h}px) and (-webkit-device-pixel-ratio: ${dpr}) and (orientation: portrait)`,
}));
